import {spawn} from 'node:child_process';
import {readFileSync} from 'node:fs';

let rss;
if (process.platform === 'darwin') {
  const {dlopen, FFIType, ptr} = await import('bun:ffi');
  const lib = dlopen('/usr/lib/libproc.dylib', {proc_pidinfo: {args: [FFIType.i32, FFIType.i32, FFIType.u64, FFIType.ptr, FFIType.i32], returns: FFIType.i32}});
  rss = pid => {
    const info = Buffer.alloc(96);
    return lib.symbols.proc_pidinfo(pid, 4, 0, ptr(info), info.length) > 0 ? Number(info.readBigUInt64LE(8)) : 0;
  };
} else {
  rss = pid => {
    try { return Number(/^VmRSS:\s+(\d+)/m.exec(readFileSync(`/proc/${pid}/status`, 'utf8'))?.[1] || 0) * 1024; } catch { return 0; }
  };
}
import {fileURLToPath} from 'node:url';

const MAX_INPUT = 64 * 1024;
const MAX_XML = 1024 * 1024;
const MAX_RSS_KB = 96 * 1024;
const unreadable = () => ({status: 422, body: {kind: 'unreadable', kept: true}});
let active = false;
const queue = [];

function parse(buffer) {
  return new Promise((resolve) => {
    const child = spawn(process.execPath, [fileURLToPath(new URL('./parser.mjs', import.meta.url))], {
      env: {}, stdio: ['pipe', 'pipe', 'ignore']
    });
    let output = Buffer.alloc(0);
    let done = false;
    let result;
    const finish = (argumentsResult) => {
      if (done) return;
      done = true;
      clearTimeout(timeout);
      clearInterval(monitor);
      result = argumentsResult;
      if (child.exitCode === null && child.signalCode === null && child.pid) child.kill('SIGKILL');
      else resolve(result);
    };
    const timeout = setTimeout(() => finish(unreadable()), 200);
    const monitor = setInterval(() => {
      if (child.pid && rss(child.pid) > MAX_RSS_KB * 1024) finish(unreadable());
    }, 5);
    child.on('error', () => finish(unreadable()));
    child.stdin.on('error', () => {});
    child.stdout.on('data', chunk => {
      output = Buffer.concat([output, chunk]);
      if (output.length > MAX_XML) finish(unreadable());
    });
    child.on('close', code => {
      if (done) return resolve(result);
      if (code !== 0) return finish(unreadable());
      const title = /<title>(.*?)<\/title>/s.exec(output.toString())?.[1];
      finish(title ? {status: 200, body: {kind: 'proposal', title}} : unreadable());
    });
    child.stdin.end(buffer);
  });
}

async function run(buffer) {
  try { return await parse(buffer); }
  finally {
    const next = queue.shift();
    if (next) next();
    else active = false;
  }
}

export async function upload(buffer) {
  if (buffer.length > MAX_INPUT) return unreadable();
  if (active) {
    if (queue.length >= 2) return {status: 503, body: {kind: 'busy'}};
    await new Promise(resolve => queue.push(resolve));
  } else active = true;
  return run(buffer);
}

